function DENSITY_SERIES_PARTIAL_SUM(density, N):
    total <- 0
    for n from 0 to N-1:
        total <- total + density(n)
    return total

function DIVERGES_BY_COMPARISON(density, N):
    for n from 0 to N-1:
        if density(n) < 1/(n+2):
            return FALSE   // comparison inconclusive
    return TRUE            // dominates harmonic => diverges

function SIMULATE_LIMSUP_INDICATOR(density, window, tail_start):
    for n from tail_start to window-1:
        if UNIFORM(0,1) < density(n):
            return TRUE
    return FALSE

function ESTIMATE_LIMSUP_PROBABILITY(density, window, tail_start, trials):
    hits <- 0
    repeat trials times:
        if SIMULATE_LIMSUP_INDICATOR(density, window, tail_start):
            hits <- hits + 1
    return hits / trials
